insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 1, 'How many inputs does a kill sheet take and how many outputs does it produce?', '["Four inputs and six outputs.", "Six inputs and four outputs, and three of the inputs can only be measured during the event.", "Nine inputs and two outputs, the two being the initial circulating pressure and the pressure schedule between them.", "As many inputs as the well has hole sections, since each section contributes its own volume and its own capacity."]'::jsonb, 1, 'The split between the standing part and the kick part is what makes it preparable but not completable in advance.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 2, 'Which of the kill sheet inputs cannot be known before a kick?', '["The pump output per stroke.", "The slow circulating rate pressure, which has to be measured with the well shut in and the choke partly open.", "The true vertical depth at the bit, because the survey is not run until after the well has been closed in.", "The two shut-in gauge readings and the pit gain."]'::jsonb, 3, 'Everything else belongs to the standing part and can be kept current between events.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 3, 'What is the initial circulating pressure?', '["The shut-in drill pipe pressure added to the slow circulating rate pressure measured at the chosen kill rate.", "The pressure at the moment of shut-in.", "The pressure reached once the kill mud is at the bit.", "The highest reading the gauge shows during the kill."]'::jsonb, 0, 'A static deficit plus a friction term. It is the pressure needed to start moving mud without losing the balance.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 4, 'Once kill mud has reached the bit, what does the drill pipe gauge settle to?', '["The shut-in casing pressure at the end.", "The initial circulating pressure less the shut-in drill pipe pressure, which leaves only the frictional component.", "The slow circulating rate pressure scaled by the ratio of kill mud density to original mud density.", "The pressure at which the choke can be fully opened without the well flowing, once the kill mud is all the way round."]'::jsonb, 2, 'Only friction remains, because the heavier column has absorbed the deficit. The scaling accounts for the denser fluid.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 5, 'Why is the final circulating pressure not simply the slow circulating rate pressure?', '["Because the pump rate is different by then.", "Because friction scales with density, and the kill mud is heavier than the mud it was measured with.", "Because the influx is still in the annulus at that point and adds a component that the original measurement did not include.", "Because the bit nozzles have eroded during the circulation and no longer produce the same pressure drop as before."]'::jsonb, 1, 'The ratio of the two densities is the whole correction, and it is a simple multiplication.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 6, 'What does the drill pipe pressure schedule describe?', '["The fall from one circulating pressure to the other.", "The rise in the casing pressure during the whole kill.", "The pressure the choke operator must hold on the annulus at each stroke count during the whole of the operation.", "The relationship between the pump rate and the pressure loss, measured at two rates before the kick was taken."]'::jsonb, 0, 'It is a line between two points, and the string displacement is its horizontal axis.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 7, 'Why is the schedule a straight line in strokes?', '["Because pressure always falls linearly.", "Because the annulus capacity is constant over the interval, so the influx rises at a steady velocity throughout.", "Because the choke is opened in equal increments, and each increment produces the same drop in surface pressure.", "Because the kill mud interface moves down the string at a uniform rate as strokes accumulate."]'::jsonb, 3, 'Uniform displacement in a uniform bore gives a uniform density change, so the surface pressure falls uniformly.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 8, 'How many points does a real kill sheet plot on the schedule?', '["Exactly two, the start and the end.", "One for every stroke of the pump, so that the operator has a target value available at any moment during the kill.", "As many as the choke operator can work with, often one every hundred strokes.", "Three, being the initial pressure, the midpoint and the final pressure, which is enough to define the straight line."]'::jsonb, 2, 'It is a line and any number of points describes it. The spacing is a presentation choice.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 9, 'What happens to the drill pipe pressure after the kill mud reaches the bit?', '["It continues to fall towards zero.", "It is held constant at the final circulating pressure for the rest of the circulation.", "It rises again as the influx approaches surface, because the expanding gas reduces the annulus hydrostatic pressure.", "It is no longer used, and the choke operator switches to holding the casing pressure at a constant value instead."]'::jsonb, 1, 'The string density stops changing, so the pressure needed to hold the bottom steady stops changing too.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 10, 'What fraction of the operation does the schedule cover?', '["Only the string displacement, which is a small part of the full cycle on both wells in this course.", "The whole of the circulation.", "Exactly half, because the string and annulus volumes are approximately equal on any conventional drilling assembly.", "The part after the influx has passed the casing shoe, which is where the pressure control becomes critical."]'::jsonb, 0, 'Strokes to bit against a full cycle. The constant-pressure phase is the longer one by far.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 11, 'What is the annulus doing during the constant-pressure phase?', '["Nothing that affects the drill pipe side.", "Holding a steady pressure, because the choke is fixed once the kill mud has arrived at the bit of the well.", "Filling with kill mud from the top down, since the heavier fluid settles ahead of the lighter mud above it.", "Everything interesting: the influx is rising and expanding while kill mud displaces original mud upward."]'::jsonb, 3, 'The casing pressure changes continuously through it, and this engine does not compute that history.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 12, 'Why does the kill sheet say nothing about the casing pressure history?', '["Because the casing gauge is unreliable.", "Because the casing pressure is held constant throughout the operation and therefore needs no schedule of its own.", "Because computing it needs a model of the influx position and expansion that this engine does not have.", "Because the choke operator works from the drill pipe gauge and never looks at the annulus side during a kill."]'::jsonb, 2, 'The operator reads the casing gauge as a limit against the MAASP rather than as a target to follow.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 13, 'What is the slow circulating rate pressure''s role in the sheet?', '["It supplies the friction term.", "It is what sets the pump rate used for the kill.", "It is compared against the shut-in casing pressure to determine whether the influx is gas or a formation liquid.", "It provides the starting point for the schedule, which then falls linearly to zero over the string displacement."]'::jsonb, 0, 'It is the only measured hydraulics input, and it lets the sheet avoid needing a hydraulics model.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 14, 'What would a wrong slow circulating rate pressure do?', '["Change only the initial pressure.", "Shift both circulating pressures by the same amount, so the bottom hole pressure is held at the wrong value.", "Have no effect, because the choke operator corrects for it by watching the casing pressure and adjusting continuously.", "Produce a schedule with the wrong slope but the correct endpoints, which the operator would notice immediately."]'::jsonb, 1, 'It appears in both endpoints, so the whole schedule moves and the error is invisible from the shape.'),
  ('wellcontrol', 'intermediate', 'module', 'm01-the-kill-sheet', 15, 'Why can a kill sheet be prepared but not completed in advance?', '["Because the form has to be signed at the time.", "Because the liners are replaced just before every kill.", "The standing part is known well in advance, but the three kick measurements do not exist until a kick happens.", "Because the two methods use incompatible sheet layouts."]'::jsonb, 2, 'That is precisely why the standing part has to be kept current at every stand.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 1, 'How is the influx height obtained from the pit gain?', '["Multiply the pit gain by the mud density.", "Divide the pit gain by the annulus capacity over the interval the influx occupies.", "Subtract the string volume from the pit gain and divide the remainder by the average capacity of the whole annulus.", "Take the ratio of the two shut-in readings and multiply it by the true vertical depth at the bit of the well."]'::jsonb, 1, 'It is one division, and the capacity is the one opposite the bottom hole assembly rather than an average.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 2, 'Why does the capacity used matter so much?', '["Because the collar annulus is much tighter than the casing annulus, so the same volume gives a very different height.", "Because capacities are hard to measure.", "Because the influx expands as it rises, and the capacity determines how much of that expansion is accommodated.", "Because the annulus capacity appears in the denominator of the kill mud calculation as well as the height one."]'::jsonb, 0, 'Using an average over the whole annulus understates the height of an influx sitting around the collars.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 3, 'How is the influx density obtained?', '["From the gas readings at the flow line.", "From the ratio of the pit gain to the annulus volume, which gives the fraction of the annulus that the influx occupies.", "From a sample taken at the choke manifold once the influx has been circulated to surface and separated.", "From the pressure difference between the two gauges, divided by gravity and the influx height."]'::jsonb, 3, 'It is the mud density less the deficit expressed as a density over the influx height.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 4, 'What does the difference between the two shut-in readings physically represent?', '["The frictional loss around the annulus.", "The margin remaining before the casing shoe reaches the fracture pressure at the current mud weight in the hole.", "The pressure the influx failed to provide compared with the mud it displaced.", "The rate at which gas is migrating up the annulus, expressed as a pressure rise per unit of elapsed time."]'::jsonb, 2, 'Both columns reach the same bottom hole pressure, so the difference is entirely down to the light fluid.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 5, 'An influx density near that of the mud in the hole means what?', '["The influx is a formation liquid rather than gas, because its density is comparable with the mud''s.", "The gauges have been misread.", "The influx has already dissolved into the mud and no longer exists as a separate phase in the annulus at all.", "The pit gain was recorded before the well had finished flowing, so the height used in the calculation is too small."]'::jsonb, 0, 'Brine and oil are heavy. Gas is light. The number separates them directly.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 6, 'What density range does the course use to classify an influx as gas?', '["Anything below the mud density.", "A low density, well below the density of any formation liquid, typically a few hundred at most.", "A density between that of fresh water and that of the mud currently circulating in the well at the time of shut-in.", "Any value the calculation returns, since the classification is made from the gas readings rather than the density."]'::jsonb, 1, 'The boundaries are conventions rather than physics, and the course states them explicitly.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 7, 'Why can a scenario named as a gas kick classify as something else?', '["Because the naming convention is arbitrary.", "Because gas dissolves into the mud during the shut-in period and the residual influx is then mostly formation water.", "Because the gauges are read at different times, so the difference between them includes a migration component.", "Because the classification comes from the arithmetic rather than from the name given to the scenario."]'::jsonb, 3, 'Naming a case gas does not make the pressure difference and the pit gain produce a gas density.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 8, 'What does a computed influx density between the gas and liquid ranges indicate?', '["That the influx is definitely oil.", "That the annulus capacity used in the height calculation was taken at the shoe rather than opposite the collars.", "A mixed influx, or a set of readings that do not fit the single bubble picture.", "That the well has taken two separate influxes from two different formations at two different points in the section."]'::jsonb, 2, 'Both readings are worth having. The second is a warning that the inputs need rechecking.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 9, 'What is the classification actually used for?', '["Deciding how urgent the situation is and how much expansion to expect on the way up the annulus.", "Reporting the event to the regulator.", "Selecting between the two kill methods, since gas kicks must always be circulated out by the Driller''s Method.", "Determining the kill mud weight, because a gas influx requires a larger safety margin above the balance point."]'::jsonb, 0, 'Gas expands and migrates. Liquid does neither to any comparable degree.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 10, 'Why does a gas influx produce a larger pressure difference than a liquid one of the same volume?', '["Because gas occupies more volume.", "Because its density is far below the mud''s, so the pressure it fails to provide over its height is much larger.", "Because the gas has already begun to expand by the time the well is shut in, which increases its height in the annulus.", "Because gas dissolves partly into the mud, which raises the effective density of the column above the influx."]'::jsonb, 1, 'The deficit is the density difference times gravity times the height, and the density difference is the large term.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 11, 'What assumption underlies the whole influx description?', '["That the influx is entirely gas.", "That the influx has not moved between the moment the well was closed and the moment the gauges were read.", "That the annulus capacity is uniform from the bit all the way up to the casing shoe of the current hole section.", "That the influx is a single continuous slug occupying the full annulus cross section."]'::jsonb, 3, 'Real influxes are dispersed and mixed. The Expert tier examines what that assumption costs.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 12, 'If the pit gain is wrong, what happens to the influx description?', '["Only the height is affected.", "Neither, because the density is computed from the pressure difference alone and does not use the pit gain at all.", "Both the height and the density are wrong, because the height feeds directly into the density.", "The classification changes but the height stays correct, since the height depends on the annulus capacity only."]'::jsonb, 2, 'It is one of the three event measurements and an error in it propagates through everything downstream.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 13, 'Why does the influx height matter more than the influx volume?', '["Because volumes are harder to measure.", "Because the pressure deficit is a density difference times gravity times a height, not a volume.", "Because the height determines the number of strokes needed to circulate the influx out of the annulus at the kill rate.", "Because the volume changes as the influx rises whereas the height is conserved throughout the circulation."]'::jsonb, 1, 'Volume becomes height by way of a capacity, and only then does it become a pressure.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 14, 'What does the influx description feed into in the Expert tier?', '["The kick tolerance calculation, which asks whether an influx of a given size would fracture the shoe.", "The kill mud weight calculation.", "The slow circulating rate pressure, which is scaled by the influx density to give the final circulating pressure.", "The choice between the two kill methods, which is made from the classification and the migration rate together."]'::jsonb, 0, 'Height, density and the single bubble assumption are all reused there directly.'),
  ('wellcontrol', 'intermediate', 'module', 'm02-what-the-influx-is', 15, 'What should you do when the influx density comes out above the mud density?', '["Accept it as a heavy brine influx.", "Reclassify the event as a lost circulation incident, since a denser fluid entering the well would displace mud outward.", "Recheck the inputs, because a heavier influx contradicts the physical picture.", "Use the mud density instead, which is the conservative choice and gives a smaller estimate of the influx height."]'::jsonb, 2, 'It means the casing gauge read lower than the drill pipe gauge, which needs an explanation before anything else.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 1, 'State the constant bottom hole pressure principle.', '["Hold the pressure at the bottom slightly above the pore pressure throughout, and below the fracture pressure everywhere.", "Hold the casing pressure constant.", "Keep the pump at a fixed rate so that the frictional component of the pressure never changes during the operation.", "Maintain the same mud weight in the string and the annulus until the influx has reached the surface."]'::jsonb, 0, 'Both halves matter. Too low admits more influx, too high breaks the shoe.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 2, 'What is the control variable during a kill?', '["The pump rate, adjusted stroke by stroke.", "The mud weight in the active system, raised progressively as the circulation proceeds towards the final value.", "The choke opening, which sets the back pressure on the annulus.", "The blowout preventer, which is opened and closed to regulate the pressure held on the annulus during the kill."]'::jsonb, 2, 'The pump is held steady so the friction term stays steady. The choke does the work.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 3, 'What is the indicator the choke operator follows?', '["The casing pressure against the MAASP.", "The drill pipe pressure, compared against the schedule at the current stroke count.", "The pit level, which shows whether the influx is being removed at the rate the calculation predicted it would be.", "The flow out at the choke manifold, held equal to the flow in so that the well neither gains nor loses volume."]'::jsonb, 1, 'The casing gauge is watched as a limit rather than followed as a target.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 4, 'Closing the choke does what to the bottom hole pressure?', '["Lowers it by restricting the flow.", "Leaves it unchanged, since the choke acts only on the surface pressure and not on the hydrostatic column below it.", "Raises it only above the casing shoe, because the restriction is transmitted no further down than the closed preventer.", "Raises it, because more back pressure on the annulus adds to the whole column."]'::jsonb, 3, 'The annulus is a connected column and a surface pressure appears at every depth in it.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 5, 'If the drill pipe pressure is above the schedule, what does the operator do?', '["Open the choke slightly, which lowers the back pressure and brings the reading down to the target.", "Close the choke to bring it back.", "Increase the pump rate, since a higher rate raises the frictional component and restores the correct total pressure.", "Stop the pump and allow the pressure to stabilise before resuming the circulation at the same stroke count."]'::jsonb, 0, 'Above the schedule means the bottom is being held too high, which risks the shoe.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 6, 'Why is the pump rate held constant during a kill?', '["Because the pump cannot be adjusted while loaded.", "Because a change in rate would alter the number of strokes required to displace the string and invalidate the count.", "So the friction component of the pressure stays constant and the schedule remains valid.", "Because the influx expands at a rate proportional to the pump rate, and a change would disturb the expansion."]'::jsonb, 2, 'The schedule is built on one measured friction term at one rate. Change the rate and the term changes.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 7, 'What must be done if the pump rate has to be changed mid kill?', '["Nothing, because strokes are conserved.", "Adjust the choke to hold the casing pressure steady through the change, then work to the new schedule.", "Stop the circulation, shut the well in again, take fresh readings and rebuild the kill sheet from the beginning.", "Recompute the influx height at the new rate, because the expansion depends on the velocity in the annulus."]'::jsonb, 1, 'Holding the casing pressure steady through the transition is what keeps the bottom hole pressure constant.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 8, 'What happens if the choke plugs during a circulation?', '["The pressure falls to zero at surface.", "The pump stalls and the circulation stops, after which the well can be reshut and the choke cleared at leisure.", "The influx stops rising, which is a safe condition provided the pumps are shut down within a short period.", "The pressure rises quickly on both gauges and the shoe is at immediate risk."]'::jsonb, 3, 'It is one of the few situations where stopping the pump quickly is the right response.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 9, 'What happens if the choke washes out?', '["The pressure falls, the well goes underbalanced, and a second influx becomes possible.", "The pressure rises uncontrollably.", "The circulation continues normally, because the choke operator can compensate by reducing the pump rate accordingly.", "The influx is expelled faster than planned, which shortens the operation without changing the bottom hole pressure."]'::jsonb, 0, 'The remedy is to switch to the second choke, which is why rigs have two.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 10, 'Why is choke response not instantaneous?', '["Because the operator reacts slowly.", "Because the choke actuator is hydraulically driven and its opening changes over a period of several minutes.", "The signal has to travel the length of the annulus as a pressure wave before it reaches the bottom.", "Because the mud is compressible and absorbs the change entirely until the whole column has equilibrated."]'::jsonb, 2, 'On a deep well the lag is appreciable and it is a reason to make small adjustments rather than large ones.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 11, 'Which mistake on the choke is the one most often made?', '["Opening the choke too far at the start.", "Chasing the gauge with large adjustments, so the pressure oscillates about the target.", "Following the casing pressure rather than the drill pipe pressure, which gives the correct answer only by coincidence.", "Reading the schedule at the wrong stroke count, which produces a steady offset rather than an oscillation."]'::jsonb, 1, 'Small early corrections beat large late ones, and the lag is what makes that true.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 12, 'What does the casing gauge tell the operator during the kill?', '["The current stroke count of the pump.", "The position of the influx in the annulus, since the pressure peaks at the moment the influx passes the casing shoe.", "The density of the kill mud that has been built, which can be inferred from the rate at which the pressure falls.", "Whether the shoe is approaching its limit, by comparison against the MAASP."]'::jsonb, 3, 'It is a limit rather than a target, and the Expert tier gives the limit its proper definition.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 13, 'What does holding a constant bottom hole pressure not do?', '["It does not stop the casing pressure from changing, and that pressure changes continuously.", "It does not remove the influx from the well.", "It does not prevent the drill pipe pressure from following the schedule down to its final circulating value.", "It does not keep the pump rate steady, which the operator must manage separately from the choke position."]'::jsonb, 0, 'Constant at the bottom means changing at surface, because the column between them is changing.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 14, 'Why is the drill pipe the indicator rather than the casing?', '["Because it is closer to the pump.", "Because the casing gauge responds more slowly to a choke movement and therefore gives a delayed indication.", "Its column is clean and known, so its reading maps directly onto the bottom hole pressure.", "Because the drill pipe pressure is the only one of the two that appears anywhere on the kill sheet."]'::jsonb, 2, 'The annulus column contains influx and kill mud at unknown positions and cannot be inverted.'),
  ('wellcontrol', 'intermediate', 'module', 'm03-holding-bottom-hole-pressure', 15, 'What is the single most important thing to avoid during a kill?', '["Running the pump above the kill rate.", "Letting the bottom hole pressure fall, because that admits a second influx on top of the first.", "Allowing the casing pressure to fall below the shut-in value, which indicates the influx has begun to migrate upward.", "Completing the circulation before the kill mud has been built to the full calculated density in the pits."]'::jsonb, 1, 'Too high risks the shoe, too low restarts the problem, and the second is the one that compounds.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 1, 'A drill pipe pressure sitting above the schedule means what about the bottom of the hole?', '["The influx has stopped rising.", "The kill mud has arrived at the bit earlier than the stroke count predicted, which shortens the whole operation.", "The bottom hole pressure is higher than intended, so the shoe is carrying more than the plan allowed.", "The pump is running below the kill rate, so the frictional part of the reading has fallen away."]'::jsonb, 2, 'Above the schedule is the direction that risks losses and, in the worst case, an underground blowout.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 2, 'What is the first thing to check when the reading sits above the schedule?', '["Whether the choke is too far closed, which is the commonest and most easily corrected cause.", "Whether a second influx has been taken.", "Whether the slow circulating rate pressure used in building the sheet was measured at the rate now being pumped.", "Whether the kill mud density in the pits matches the value the calculation called for at the time of shut-in."]'::jsonb, 0, 'Check the simple mechanical cause before reaching for an interpretation of the well.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 3, 'A reading below the schedule means what?', '["The choke has been closed too far.", "The bottom hole pressure has fallen away, and the well may well be taking a further influx on top of the first.", "The kill mud is heavier than intended, so the string column is providing more pressure than the sheet allowed for.", "The influx has been circulated past the casing shoe and the annulus is now lighter than it was at shut-in."]'::jsonb, 1, 'It is the more dangerous of the two directions, because it compounds the original problem.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 4, 'Which mechanical cause of that low value should you look at first?', '["A washed out bit nozzle.", "A drop in the pump rate, which removes part of the frictional component of the reading at the standpipe gauge.", "Gas expanding in the annulus, which lightens the column and reduces the pressure needed at the surface.", "The choke opened too far, which is corrected by closing it slightly."]'::jsonb, 3, 'Both a choke movement and a pump rate change produce it, and the choke is the one to check first.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 5, 'How do you distinguish a choke problem from a second influx?', '["Watch the pit volume.", "By the shape that the pressure trace makes over time.", "By comparing the two gauges against one another.", "By stopping the pump and watching for a recovery."]'::jsonb, 0, 'A pressure change with no volume change is mechanical. A pressure change with a gain is the well.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 6, 'What is the response to a confirmed second influx?', '["Increase the pump rate to compensate.", "Continue the circulation and correct the schedule for the additional volume once the first influx is at surface.", "Shut the well in again, take fresh readings and rebuild the sheet.", "Raise the kill mud density by the amount needed to balance the combined underbalance of both influxes together."]'::jsonb, 2, 'The sheet was built on one set of measurements and those measurements are no longer valid.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 7, 'A rising drill pipe pressure with a falling casing pressure suggests what?', '["A washout in the drill pipe.", "A restriction developing in the string, such as a partly plugged bit nozzle.", "Gas migration in the annulus, which raises the surface reading on the string side as the bubble rises past the shoe.", "The kill mud reaching the bit, at which point the two gauges naturally diverge for the rest of the circulation."]'::jsonb, 1, 'The two gauges moving in opposite directions points to something between them rather than to the formation.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 8, 'Now take the string side falling while the annulus side holds steady. Diagnosis?', '["A plugged bit nozzle.", "A second influx entering below the bit, which lightens the annulus column and reduces the pressure required at surface.", "The pump losing efficiency, which reduces the actual displacement per stroke below the value used in the sheet.", "A washout in the string, which is losing pressure before the bit."]'::jsonb, 3, 'A washout short circuits part of the friction, so the string side reads lower for the same bottom hole pressure.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 9, 'Why is a plugged nozzle worse than a washout for the kill?', '["Because it raises the pressure needed to circulate and can push the whole system beyond its limits.", "Because it cannot be detected.", "Because it makes the drill pipe pressure read low, which the operator corrects by closing the choke and raising the bottom.", "Because it changes the pump output per stroke, which invalidates every stroke count on the standing part of the sheet."]'::jsonb, 0, 'A washout makes the reading unreliable. A plug makes the operation harder to complete at all.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 10, 'What is the correct action when the readings stop making sense?', '["Increase the pump rate a little and then observe.", "Continue at the current settings until the kill mud reaches the bit, which resolves most ambiguities automatically.", "Stop, shut in and think.", "Open the choke fully to relieve the annulus and re-establish a known condition before resuming the operation."]'::jsonb, 2, 'The well is safe shut in. It is not safe being circulated on a sheet that no longer describes it.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 11, 'What does shutting in mid kill cost?', '["The whole kill sheet becomes invalid.", "Time and some gas migration, both of which are recoverable.", "The influx position is lost, so the circulation has to begin again from the start with a fresh bottoms up.", "The kill mud already in the string settles out, and the density has to be rebuilt before circulation can restart."]'::jsonb, 1, 'Against the cost of continuing on wrong assumptions, that is a cheap price.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 12, 'Why does the sheet need rebuilding after a second influx?', '["Because the pump rate will have changed.", "Because the kill mud density calculated originally is no longer sufficient to balance the deeper of the two formations.", "Because the stroke counts are measured from the start of the circulation and cannot be restarted partway through.", "Because its inputs were the shut-in readings and the pit gain from the first event only."]'::jsonb, 3, 'Six inputs, three of which are now different. The arithmetic has to be redone.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 13, 'What does a steady divergence between the two gauges over many strokes mean?', '["Something in the system is changing that the sheet did not anticipate, and it needs identifying.", "Normal behaviour during a kill.", "The influx is passing the casing shoe, which is the expected point of maximum divergence during any circulation.", "The kill mud front has become dispersed, which spreads the pressure change over a longer interval of strokes."]'::jsonb, 0, 'The gauges are supposed to move in a predictable relationship. A drift is information.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 14, 'What is the value of writing down the readings at every schedule point?', '["It is required for the incident report.", "It allows the pump efficiency to be recalculated from the observed pressures at successive stroke counts during the kill.", "It turns a set of impressions into a record that can be read back and diagnosed.", "It gives the choke operator a reference so that the same adjustment can be repeated at the same point next time."]'::jsonb, 2, 'Diagnosing a divergence needs a history, and a history has to have been recorded to exist.'),
  ('wellcontrol', 'intermediate', 'module', 'm04-reading-the-sheet-back', 15, 'What is the general rule for reading the sheet back?', '["Every deviation means a second influx.", "A deviation is either mechanical or it is the well, and volume tells you which.", "A deviation upward is always mechanical and a deviation downward is always the well responding to the circulation.", "Deviations should be ignored unless they exceed ten percent of the initial circulating pressure at that stroke."]'::jsonb, 1, 'The pit volume is the discriminator, and it is available at every moment of the operation.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 1, 'What is a golden file?', '["A published industry reference case.", "A recorded set of engine outputs for a fixed set of inputs, checked on every build.", "A calibration data set collected from field operations and used to tune the engine''s empirical coefficients.", "A set of acceptance criteria that the engine must satisfy before it can be promoted to the next validation tier."]'::jsonb, 1, 'It catches change rather than error. A wrong answer recorded as a golden stays wrong and stays green.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 2, 'What does a passing golden prove?', '["That the engine still returns what it returned when the file was recorded, and nothing more than that.", "That the engine is correct.", "That the engine agrees with the published well control literature to within the stated numerical tolerance.", "That the calculation has been reviewed by a second engineer and signed off against the validation reference."]'::jsonb, 0, 'Regression protection is valuable and it is not the same thing as validation.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 3, 'What is the hand-built example in this course for?', '["To provide a golden file for the build.", "To calibrate the pump efficiency used in the stroke calculations against a case with a known and published answer.", "To check the engine against arithmetic a person can do on paper.", "To demonstrate the difference between the Driller''s Method and the Wait and Weight Method on the same well."]'::jsonb, 2, 'Round numbers chosen so every intermediate quantity comes out clean and can be verified by hand.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 4, 'Why are the hand example''s inputs round numbers?', '["Because the source published them that way.", "Because rounding the inputs removes the floating point error that would otherwise accumulate through the calculation.", "Because the engine requires whole numbers for the depth and capacity inputs to its volume routine.", "So that every intermediate result is checkable without a calculator."]'::jsonb, 3, 'A closed form you can verify in your head is worth more than one you have to trust.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 5, 'What does agreement between the engine and the hand example establish?', '["That the engine is validated for field use.", "That the engine implements the same arithmetic on that particular case.", "That the engine''s treatment of gas expansion matches the published industry method for all influx sizes and depths.", "That the assumptions in the model are appropriate for the well conditions the course is teaching against."]'::jsonb, 1, 'One case, one set of formulas. It says nothing about the cases the example does not cover.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 6, 'Which quantity in the course has the cleanest closed form?', '["The kill mud density, which is a division and an addition and can be checked in one line.", "The kick tolerance in the circulated case.", "The pressure schedule, because it is a straight line and only its two endpoints need to be verified independently.", "The influx density, since it follows directly from the difference between the two shut-in gauge readings."]'::jsonb, 0, 'Several quantities in the course have closed forms. That one is the shortest.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 7, 'What does a closed form check catch that a golden does not?', '["A change introduced by a later edit.", "A difference between two versions of the engine that produce the same output for the recorded inputs but not for others.", "An error that was present when the golden was first recorded.", "A numerical instability that appears only when the inputs are close to the limits of the engine''s valid range."]'::jsonb, 2, 'Goldens freeze behaviour. Closed forms test it against something outside the engine.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 8, 'Why does the course carry both goldens and closed forms?', '["Because the build requires two test types.", "Because the goldens cover the volume calculations and the closed forms cover the pressure calculations separately.", "Because a closed form cannot be automated and therefore has to be supplemented by a recorded output file.", "Because they fail in different ways, so together they cover more than either alone."]'::jsonb, 3, 'One catches drift, the other catches a wrong starting point. Neither substitutes for the other.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 9, 'What is the difference between validation and regression testing?', '["Validation compares against an external truth, regression compares against the engine''s own previous output.", "There is no practical difference.", "Validation is run before release and regression is run afterwards, but both compare against the same reference data.", "Validation uses field measurements while regression uses synthetic cases constructed to exercise every code path."]'::jsonb, 0, 'That distinction runs through every course in this series and it is worth carrying.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 10, 'What would it take to validate this engine properly?', '["More golden files at more conditions.", "Comparison against published well control worked examples and against recorded field kill records.", "A second implementation of the same equations, written independently, and a comparison of the two sets of outputs.", "A sensitivity study showing that the outputs vary smoothly with each input across the whole of the design range."]'::jsonb, 1, 'External truth is the requirement, and the course states which of it is currently in hand.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 11, 'What does the course claim about its own validation status?', '["That the engine is fully field validated.", "That validation is unnecessary because the calculations are standard and have been in industry use for decades.", "That the arithmetic is checked and that field validation is a separate and larger question.", "That the golden files constitute validation, since they were recorded from a reviewed and approved implementation."]'::jsonb, 2, 'Stating the status honestly is what makes the course usable by somebody who was not in the room.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 12, 'If the engine and the hand example disagreed, what would that mean?', '["The engine should be trusted over the arithmetic.", "One of the two is wrong, and the hand example is the easier one to check.", "The disagreement is expected, because the hand example uses simplifications the engine does not make in its model.", "The golden files would have caught it already, so the disagreement must be in the way the inputs were entered."]'::jsonb, 1, 'A disagreement is information. Which side is wrong is decided by rechecking, not by preference.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 13, 'Why does the influx height in the hand example come out to a round number?', '["Because the inputs were chosen so that the division produces one, which makes the check easy.", "Because influx heights are always round.", "Because the engine rounds its outputs to a fixed number of significant figures before writing them to the golden file.", "Because the annulus capacity used in the example is the average over the whole hole rather than the value at the collars."]'::jsonb, 0, 'Choosing the inputs to make the arithmetic clean is the whole design of a hand check.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 14, 'What is the risk in relying only on goldens?', '["Goldens are slow to run.", "Goldens cover only the inputs they were recorded at, so behaviour at other conditions is entirely untested by them.", "Goldens have to be regenerated whenever the engine changes, which makes them expensive to maintain over time.", "An error recorded once is protected forever and never questioned again."]'::jsonb, 3, 'The second point is true as well. The first is the one that matters most.'),
  ('wellcontrol', 'intermediate', 'module', 'm05-against-the-oracle', 15, 'What should a learner take from this module into practice?', '["Trust engine output that passes its tests.", "Recompute every engine result by hand before using it, since automated tests cannot establish physical correctness.", "Ask what a test compares against before treating a green result as evidence.", "Prefer engines with more golden files, because coverage of more conditions gives a stronger correctness guarantee."]'::jsonb, 2, 'The question is always what the reference is, and whether it came from outside the software.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'What is the Professional tier''s one sentence?', '["A kill sheet turns three measurements and a standing part into a schedule somebody can follow on a gauge.", "Hold the bottom hole pressure constant.", "The influx description is the bridge between the shut-in readings and the kick tolerance work of the Expert tier.", "Every deviation from the schedule is either mechanical or it is the well, and the pit volume decides which."]'::jsonb, 0, 'The other statements are true and are parts of it. That one is the whole of it.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Which well does the Professional capstone grade?', '["The horizontal well from the lessons.", "Both wells, with the kill sheet fields taken from one and the influx description fields taken from the other.", "The slant well, on a kick the lessons did not run.", "Whichever well the learner opens in the kill sheet panel before beginning the capstone attempt for the tier."]'::jsonb, 2, 'The scenario is specific to the capstone, so no lesson prints any of its answers.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'How many of the six graded fields are kill sheet outputs?', '["All six, since the influx feeds the sheet.", "Four of them, with the other two describing the influx.", "Two, being the initial and final circulating pressures, with the remaining four describing the influx and the formation.", "Three, one for each of the measurements taken at the moment the well was shut in after the kick."]'::jsonb, 1, 'Kill mud density, formation pressure and the two circulating pressures on one side. Influx density and height on the other.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Why is the capstone''s kick different from the two lesson scenarios?', '["Because it is a harder case to solve.", "Because the two lesson scenarios are both liquid influxes and the capstone requires a gas influx to be classified.", "Because the capstone runs on a different well, and the lesson scenarios were designed for the horizontal geometry.", "So that no graded value is a number a lesson has already printed."]'::jsonb, 3, 'That is the design rule for every capstone in this series and it is applied deliberately.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Which field should be computed first?', '["The formation pressure, because the kill mud density follows from it and both use the same depth.", "The influx height, from the pit gain.", "The initial circulating pressure, since it is the sum of a measured reading and a measured friction term.", "The final circulating pressure, because it needs only the density ratio and the slow circulating rate value."]'::jsonb, 0, 'Working in dependency order means an error shows up once rather than propagating unnoticed.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Which of the graded fields needs no arithmetic beyond an addition?', '["The kill mud density.", "The influx density, which follows from the difference between the two gauge readings and nothing else at all.", "The initial circulating pressure, which is two measured numbers added together.", "The formation pressure, since it is the shut-in reading plus a column that the standing part already supplies."]'::jsonb, 2, 'The formation pressure needs the column computed first. The initial circulating pressure needs nothing computed.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'What is the trap in the influx height field?', '["Forgetting to convert from feet.", "Using an average annulus capacity instead of the one opposite the collars where the influx sits.", "Using the pit gain from the wrong scenario, since the capstone and the lessons use different gains on the same well.", "Computing the height from the pressure difference rather than from the volume, which gives a different answer."]'::jsonb, 1, 'The collar annulus is much tighter, so an average understates the height substantially.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'And what makes the density value easy to get wrong?', '["It requires a gas law calculation.", "The density has to be computed at the bottom hole conditions rather than at the surface, using the pressure at the bit.", "The two gauge readings have to be corrected for the choke line friction before the difference between them is taken.", "It depends on the height, so an error in the height carries straight into it."]'::jsonb, 3, 'Two of the six fields are linked. Getting the first one wrong costs both.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'What does the capstone''s tolerance policy reflect?', '["That the quantities are deterministic, so a correct method reproduces them to many figures.", "That the grading system is strict by design.", "That the engine''s numerical precision is limited, so the tolerances are set at the level of that limitation.", "That field measurements carry uncertainty, so the tolerances allow for the spread a real gauge would show."]'::jsonb, 0, 'There is no measurement noise in a calculation. A wide tolerance would only hide a wrong method.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What does the tier hand to the Expert tier?', '["The completed kill sheet schedule.", "The standing part of the kill sheet, which the Expert tier uses to compute the maximum allowable surface pressure.", "The influx description and the single bubble assumption behind it.", "The choice between the two kill methods, which the Expert tier converts into a casing point recommendation."]'::jsonb, 2, 'Kick tolerance reuses the height, the density and the assumption directly.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What does the Expert tier add that this one does not have?', '["A treatment of gas migration in time.", "A limit at the casing shoe, and the question of whether the influx would break it.", "The pressure schedule for the annulus side, which this tier deliberately leaves out because it cannot be computed.", "A method for classifying the influx from the gas readings rather than from the computed density value."]'::jsonb, 1, 'Everything here holds the bottom steady. The next tier asks what the shoe can stand while you do.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Which habit does this tier name as most useful?', '["Memorising the four kill sheet outputs.", "Rebuilding the kill sheet at every casing point, so that the standing part never becomes stale during the section.", "Comparing the influx classification against the gas readings at the flow line as an independent check.", "Recording the readings at every schedule point, so a divergence can be diagnosed later."]'::jsonb, 3, 'A diagnosis needs a history, and a history only exists if somebody wrote it down.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What is the relationship between the influx height and the kill sheet?', '["None directly. The sheet does not use it, and the Expert tier does.", "The height sets the initial circulating pressure.", "The height determines the number of strokes required to circulate the influx out of the annulus at the kill rate.", "The height is subtracted from the true vertical depth at the bit before the formation pressure is computed."]'::jsonb, 0, 'That is worth noticing: the influx description is built for the next tier rather than for this one.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Why does the course compute the influx description at all if the sheet does not use it?', '["Because the regulator requires it.", "Because the kill mud density calculation uses the influx density to correct for the fluid displaced from the annulus.", "Because it is what the kick tolerance calculation needs, and because it tells you what you are dealing with.", "Because the classification determines which of the two kill methods can safely be used on the well."]'::jsonb, 2, 'Urgency and expansion follow from the classification, and both matter during the operation.'),
  ('wellcontrol', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What should you carry out of this tier?', '["That the choke controls the pump rate.", "That a kill sheet is arithmetic on measurements, and that its schedule describes only part of the operation.", "That the casing pressure history is the primary output of the kill sheet and the drill pipe schedule is a check on it.", "That the influx classification determines the kill method and therefore the shape of the pressure schedule."]'::jsonb, 1, 'The constant-pressure phase after the bit is the longer part, and the sheet says nothing about the annulus during it.'),
  ('wellcontrol', 'intermediate', 'final', null, 1, 'Count the boxes on a blank sheet. How many go in, and how many come out?', '["Six inputs, four outputs, with three inputs available only during the event.", "Four inputs and six outputs.", "Nine inputs and two outputs, the outputs being the two circulating pressures at either end of the schedule.", "As many as the well has hole sections, since each contributes its own volume and its own annulus capacity."]'::jsonb, 0, 'That split is why a sheet can be prepared in advance but never completed in advance.'),
  ('wellcontrol', 'intermediate', 'final', null, 2, 'Which three inputs come only from the kick?', '["The pump output, the mud weight and the bit depth.", "The two shut-in gauge readings and the pit gain.", "The slow circulating rate pressure at both rates, together with the volumetric efficiency measured at the same time.", "The fracture gradient, the pore pressure and the temperature, all of which change as the section is drilled."]'::jsonb, 1, 'Everything else belongs to the standing part and is kept current between events.'),
  ('wellcontrol', 'intermediate', 'final', null, 3, 'At the very start of the pumping, what value should the string gauge be brought to?', '["The shut-in casing pressure plus friction.", "The final circulating pressure multiplied by the ratio of the kill mud density to the original mud density.", "The shut-in drill pipe pressure plus the slow circulating rate pressure.", "The formation pressure less the hydrostatic pressure of the kill mud at the true vertical depth of the bit."]'::jsonb, 2, 'A static deficit plus a friction term, and both are measured rather than computed.'),
  ('wellcontrol', 'intermediate', 'final', null, 4, 'And once kill mud is at the bit, the gauge settles to which value?', '["The shut-in drill pipe pressure alone.", "The initial circulating pressure less the shut-in casing pressure, which removes the influx contribution from it.", "The pressure at which the choke can be fully opened without the well flowing once the kill is complete.", "The slow circulating rate pressure scaled by the density ratio."]'::jsonb, 3, 'Only friction is left, because the heavier column has absorbed the deficit entirely.'),
  ('wellcontrol', 'intermediate', 'final', null, 5, 'Why does the density ratio appear in the final circulating pressure?', '["Because frictional pressure loss scales with density and the kill mud is heavier than the mud it was measured with.", "Because the pump rate changes.", "Because the influx remaining in the annulus adds a hydrostatic component proportional to the density difference.", "Because the bit nozzles erode during the circulation and the pressure drop across them changes accordingly."]'::jsonb, 0, 'One multiplication, and it is the whole of the correction.'),
  ('wellcontrol', 'intermediate', 'final', null, 6, 'The schedule between the two circulating pressures is drawn against what?', '["Elapsed time from the start of the kill.", "Strokes, over the string displacement only.", "The volume of kill mud built in the pits, which advances at a rate set by the barite addition and the mixing capacity.", "The casing pressure, which is plotted against the drill pipe pressure to give the operator a single working curve."]'::jsonb, 1, 'Strokes survive a pump rate change. Time does not.'),
  ('wellcontrol', 'intermediate', 'final', null, 7, 'The schedule is a straight line because of what?', '["Pressure always falls linearly with volume.", "The annulus capacity is constant over the interval, so the influx rises at a steady velocity throughout the phase.", "The kill mud interface moves down a uniform bore at a uniform rate.", "The choke is opened in equal increments and each increment produces an equal drop in the surface pressure."]'::jsonb, 2, 'Uniform displacement gives a uniform density change and therefore a uniform pressure change.'),
  ('wellcontrol', 'intermediate', 'final', null, 8, 'The heavy mud has arrived at the nozzles. From here on, how is the string gauge handled?', '["Continues to fall towards zero.", "Rises again as the influx nears surface, because the expanding gas reduces the hydrostatic pressure in the annulus.", "Ceases to be used, and the operator switches to holding the casing pressure at a constant value for the remainder.", "Holds constant at the final circulating pressure."]'::jsonb, 3, 'The string density has stopped changing, so the pressure needed to hold the bottom steady stops changing.'),
  ('wellcontrol', 'intermediate', 'final', null, 9, 'The constant-pressure phase covers what part of the operation?', '["The larger part, since the annulus is far bigger than the string on both wells.", "A negligible part of the operation.", "Exactly half, because the string and the annulus volumes are approximately equal on a conventional assembly.", "Only the interval between the influx passing the casing shoe and the influx reaching the surface choke."]'::jsonb, 0, 'The schedule is the short part. Most of the kill is spent holding one number.'),
  ('wellcontrol', 'intermediate', 'final', null, 10, 'The kill sheet says nothing about the casing pressure history because of what?', '["The casing gauge is not reliable enough.", "Computing it needs a model of the influx position and expansion that this engine does not have.", "The casing pressure is held constant throughout the operation and therefore does not need a schedule of its own.", "The choke operator works from the drill pipe gauge alone and has no reason to look at the annulus side at all."]'::jsonb, 1, 'The operator reads the casing gauge against a limit rather than following it as a target.'),
  ('wellcontrol', 'intermediate', 'final', null, 11, 'An error in the slow circulating rate pressure does what?', '["Changes only the initial pressure.", "Produces a schedule with the correct endpoints but the wrong slope, which the operator would spot immediately.", "Shifts both endpoints equally, so the bottom is held at the wrong value throughout.", "Has no effect, because the operator corrects continuously by watching the casing pressure against the shut-in value."]'::jsonb, 2, 'The whole schedule moves, and the error cannot be detected from the shape of the line.'),
  ('wellcontrol', 'intermediate', 'final', null, 12, 'The influx height comes from what?', '["The pit gain divided by the annulus capacity where the influx sits.", "The pressure difference divided by gravity.", "The ratio of the shut-in casing pressure to the shut-in drill pipe pressure, scaled by the depth at the bit.", "The pit gain multiplied by the ratio of the mud density to the density computed for the influx itself."]'::jsonb, 0, 'One division, and the capacity is the one opposite the collars rather than an average.'),
  ('wellcontrol', 'intermediate', 'final', null, 13, 'Using an average annulus capacity does what to the influx height?', '["Overstates it substantially.", "Leaves it unchanged, since the total annulus volume is what determines the height of a slug within it.", "Makes it indeterminate, because an average capacity cannot be assigned to any particular depth interval.", "Understates it, because the influx sits where the annulus is tightest."]'::jsonb, 3, 'A tighter annulus gives a taller influx for the same volume.'),
  ('wellcontrol', 'intermediate', 'final', null, 14, 'Which calculation gives you how heavy the influx is?', '["The gas readings at the flow line.", "The gauge difference divided by gravity and the influx height, subtracted from the mud density.", "The ratio of the pit gain to the annulus volume, which gives the fraction of the annulus the influx occupies.", "A sample taken at the choke once the influx has been circulated to surface and passed through the separator."]'::jsonb, 1, 'It is a pressure deficit converted into a density over a known height.'),
  ('wellcontrol', 'intermediate', 'final', null, 15, 'The difference between the two shut-in gauges represents what?', '["The frictional loss around the annulus.", "The margin remaining before the shoe reaches its fracture pressure at the mud weight currently in the hole.", "The pressure the influx failed to provide compared with the mud it displaced.", "The rate at which gas is migrating upward, expressed as a pressure rise per unit of time elapsed."]'::jsonb, 2, 'Both columns reach the same bottom hole pressure, so the difference is down to the light fluid alone.'),
  ('wellcontrol', 'intermediate', 'final', null, 16, 'An influx density close to the mud density means what?', '["It is a formation liquid rather than gas.", "The gauges were misread.", "The influx has dissolved into the mud and no longer exists as a separate phase anywhere in the annulus.", "The pit gain was recorded too early, so the height used in the density calculation is smaller than the true one."]'::jsonb, 0, 'Brine and oil are heavy, gas is light, and the number separates them directly.'),
  ('wellcontrol', 'intermediate', 'final', null, 17, 'A case labelled gas returns a heavy influx density. Explain how that is possible.', '["Because the naming convention is arbitrary.", "Because the classification comes from the arithmetic rather than from the name.", "Because gas dissolves into the mud during the shut-in period and the residual influx is then mostly formation water.", "Because the two gauges are read at different moments, so migration contaminates the difference between them."]'::jsonb, 1, 'Naming a case gas does not make the pit gain and the gauge difference produce a gas density.'),
  ('wellcontrol', 'intermediate', 'final', null, 18, 'Having decided gas, liquid or mixed, what decision does that label actually inform?', '["Reporting the incident to the regulator.", "Selecting between the two kill methods, since a gas influx must always be removed by the Driller''s Method.", "Setting the kill mud weight, because a gas influx needs a larger margin above the calculated balance point.", "Judging urgency and expected expansion on the way up."]'::jsonb, 3, 'Gas expands and migrates. Liquid does neither to any comparable extent.'),
  ('wellcontrol', 'intermediate', 'final', null, 19, 'Height and density both rest on one picture of the influx. Describe that picture.', '["That the influx is entirely gas.", "That the influx has not moved between the moment of closure and the moment the gauges were read and recorded.", "A single continuous slug filling the annulus cross section.", "That the annulus capacity is uniform from the bit up to the casing shoe of the current hole section."]'::jsonb, 2, 'The Expert tier examines what that assumption costs and in which direction it errs.'),
  ('wellcontrol', 'intermediate', 'final', null, 20, 'The constant bottom hole pressure principle has two halves. What are they?', '["Above the pore pressure everywhere, and below the fracture pressure everywhere.", "Constant pump rate and constant choke position.", "The drill pipe pressure follows the schedule while the casing pressure is held at its shut-in value throughout.", "The mud weight is raised to the kill value before circulation and held there until the influx is at surface."]'::jsonb, 0, 'Too low admits more influx. Too high breaks the shoe. Both are failures.'),
  ('wellcontrol', 'intermediate', 'final', null, 21, 'Something has to be moved to keep the bottom steady. Which piece of equipment is it?', '["The pump rate, adjusted continuously.", "The choke opening, which sets the annulus back pressure.", "The mud weight in the active system, raised progressively as the circulation proceeds towards its final value.", "The blowout preventer, opened and closed to regulate the pressure being held on the annulus of the well."]'::jsonb, 1, 'The pump is held steady so that the friction term stays steady.'),
  ('wellcontrol', 'intermediate', 'final', null, 22, 'Which gauge does the person on the choke actually work to, minute by minute?', '["The casing pressure against the MAASP.", "The pit level, which shows whether the influx is leaving the well at the rate the calculation predicted for it.", "The flow out at the choke, held equal to the flow in so that the well neither gains nor loses any volume.", "The drill pipe pressure against the schedule."]'::jsonb, 3, 'The casing gauge is a limit to watch rather than a target to follow.'),
  ('wellcontrol', 'intermediate', 'final', null, 23, 'The operator winds the choke in a little. Trace the effect down to the bit.', '["Lowers it by restricting the flow.", "Leaves it unchanged, since the choke acts on the surface pressure only and not on the hydrostatic column below.", "Raises it, because the back pressure appears at every depth in the annulus.", "Raises it above the casing shoe only, because the restriction is not transmitted past the closed preventer."]'::jsonb, 2, 'The annulus is a connected column and a surface pressure appears throughout it.'),
  ('wellcontrol', 'intermediate', 'final', null, 24, 'Nothing on the sheet allows for a changing rate. Why is that acceptable in practice?', '["So the friction term stays constant and the schedule stays valid.", "Because the pump cannot be adjusted under load.", "Because a rate change would alter the strokes needed to displace the string and invalidate the stroke count.", "Because the influx expands in proportion to the pump rate and a change would disturb the expansion profile."]'::jsonb, 0, 'The schedule is built on one measured friction term at one rate.'),
  ('wellcontrol', 'intermediate', 'final', null, 25, 'If the rate must change mid kill, what is done?', '["Nothing, because strokes are conserved.", "Hold the casing pressure steady through the change, then work to the new schedule.", "Stop the circulation, shut in, take fresh readings and rebuild the entire kill sheet from the beginning again.", "Recompute the influx height at the new rate, because the expansion depends on the annular velocity."]'::jsonb, 1, 'Holding the casing pressure steady through the transition holds the bottom hole pressure constant.'),
  ('wellcontrol', 'intermediate', 'final', null, 26, 'A plugged choke produces what?', '["A fall to zero at the surface.", "A stalled pump and a stopped circulation, after which the well can be reshut and the choke cleared at leisure.", "A quick rise on both gauges and immediate risk to the shoe.", "A halt to the influx rise, which is a safe condition provided the pumps are shut down within a short period."]'::jsonb, 2, 'It is one of the few cases where stopping the pump quickly is the right response.'),
  ('wellcontrol', 'intermediate', 'final', null, 27, 'Now suppose that choke erodes open instead. What follows?', '["An uncontrollable pressure rise.", "A normal circulation, since the operator can compensate for the loss by reducing the pump rate proportionally.", "A faster expulsion of the influx, which shortens the operation without altering the bottom hole pressure.", "Falling pressure, underbalance, and the risk of a second influx."]'::jsonb, 3, 'The remedy is the second choke, which is why rigs have two.'),
  ('wellcontrol', 'intermediate', 'final', null, 28, 'A movement at surface takes a moment to be felt downhole. What accounts for the delay?', '["The pressure change travels the annulus as a wave before it reaches the bottom.", "The operator''s reaction time.", "The choke actuator is hydraulically driven and takes several minutes to move between two given positions.", "The mud is compressible and absorbs the change completely until the whole column has come to equilibrium."]'::jsonb, 0, 'On a deep well the lag is appreciable, which is why small adjustments beat large ones.'),
  ('wellcontrol', 'intermediate', 'final', null, 29, 'The string gauge is reading high against its target. What is happening at the bottom?', '["The influx has stopped rising.", "The bottom hole pressure is too high and the shoe is carrying more than planned.", "The kill mud has reached the bit sooner than the stroke count predicted, which shortens the operation.", "The pump has fallen below the kill rate and the frictional part of the reading has been lost."]'::jsonb, 1, 'It is the direction that risks losses and an underground blowout.'),
  ('wellcontrol', 'intermediate', 'final', null, 30, 'Now the string gauge is low against its target. What does that indicate downhole?', '["The choke was closed too far.", "The kill mud is heavier than intended, so the string column provides more pressure than the sheet allowed for.", "The bottom hole pressure has fallen and a further influx is possible.", "The influx has passed the casing shoe and the annulus above it is lighter than it was at the moment of shut-in."]'::jsonb, 2, 'It is the more dangerous direction, because it compounds the original problem.'),
  ('wellcontrol', 'intermediate', 'final', null, 31, 'Two very different causes give a similar gauge movement. Which observation separates them?', '["By the shape of the pressure trace.", "By comparing the two gauges, since a second influx raises the casing side and leaves the drill pipe side unchanged.", "By stopping the pump and seeing whether the pressure recovers to its shut-in value within a few minutes.", "By the pit volume, which changes for one and not the other."]'::jsonb, 3, 'A pressure change with no volume change is mechanical.'),
  ('wellcontrol', 'intermediate', 'final', null, 32, 'You have established that the well took more fluid mid kill. What now?', '["Shut in, take fresh readings, and rebuild the sheet.", "Increase the pump rate to compensate.", "Continue circulating and correct the schedule for the extra volume once the first influx has reached surface.", "Raise the kill mud density enough to balance the combined underbalance of both of the influxes together."]'::jsonb, 0, 'The sheet was built on measurements that are no longer valid.'),
  ('wellcontrol', 'intermediate', 'final', null, 33, 'One gauge climbs while the other drops. Where is the fault likely to be?', '["A washout in the drill pipe.", "A restriction in the string, such as a partly plugged nozzle.", "Gas migration in the annulus, which raises the string side reading as the bubble passes the casing shoe.", "The kill mud reaching the bit, at which point the two gauges naturally diverge for the rest of the circulation."]'::jsonb, 1, 'Gauges moving in opposite directions point to something between them rather than to the formation.'),
  ('wellcontrol', 'intermediate', 'final', null, 34, 'Reverse it: the string side drops while the annulus side holds. Diagnosis?', '["A plugged bit nozzle.", "A second influx below the bit, which lightens the annulus and reduces the surface pressure needed to hold it.", "A washout in the string, losing pressure before the bit.", "A loss of pump efficiency, which reduces the displacement per stroke below the value used to build the sheet."]'::jsonb, 2, 'A washout short circuits part of the friction, so the string side reads lower for the same bottom hole pressure.'),
  ('wellcontrol', 'intermediate', 'final', null, 35, 'Nothing you observe matches the sheet any more. What should be done?', '["Shut in and think, rather than continuing to adjust the choke.", "Increase the pump rate and observe.", "Continue until the kill mud reaches the bit, which resolves most ambiguities without any further intervention.", "Open the choke fully to relieve the annulus and re-establish a known condition before resuming the kill."]'::jsonb, 0, 'The well is safe shut in. It is not safe being circulated on a sheet that no longer describes it.'),
  ('wellcontrol', 'intermediate', 'final', null, 36, 'What does a golden file prove when it passes?', '["That the engine is correct.", "That the engine agrees with the published well control literature to within the stated numerical tolerance.", "That the implementation has been reviewed and signed off against the documented validation reference.", "That the engine still returns what it returned when the file was recorded."]'::jsonb, 3, 'Regression protection is valuable and it is not validation.'),
  ('wellcontrol', 'intermediate', 'final', null, 37, 'Why does the course carry a worked case with deliberately round inputs?', '["Providing an extra golden file.", "Checking the engine against arithmetic a person can do on paper.", "Calibrating the pump efficiency against a case whose answer has been published in the industry literature.", "Demonstrating the difference between the two kill methods on a single well and a single influx size."]'::jsonb, 1, 'Round numbers chosen so every intermediate result comes out clean.'),
  ('wellcontrol', 'intermediate', 'final', null, 38, 'Name the failure mode a recorded output file is blind to.', '["A change introduced by a later edit.", "A difference between engine versions that agree on the recorded inputs but disagree at other conditions.", "An error present when the golden was first recorded.", "A numerical instability that appears only when the inputs approach the limits of the valid range."]'::jsonb, 2, 'Goldens freeze behaviour. Closed forms test it against something outside the software.'),
  ('wellcontrol', 'intermediate', 'final', null, 39, 'Validation and regression differ how?', '["Validation compares against external truth, regression against the engine''s own past output.", "They are two words for the same thing.", "Validation runs before release and regression afterwards, but both use the same reference data set.", "Validation uses field measurements while regression uses synthetic cases that exercise every code path."]'::jsonb, 0, 'That distinction runs through every course in this series.'),
  ('wellcontrol', 'intermediate', 'final', null, 40, 'You are about to attempt this tier. Which geometry does it put in front of you?', '["The horizontal well from the lessons.", "The slant well, on a kick the lessons never ran.", "Both wells, with the sheet fields from one and the influx description fields taken from the other one.", "Whichever of the two the learner opens in the kill sheet panel before starting the attempt."]'::jsonb, 1, 'The scenario is capstone-specific, so no lesson prints any of its answers.'),
  ('wellcontrol', 'intermediate', 'final', null, 41, 'Two of the six graded fields are linked. Which pair?', '["The two circulating pressures.", "The formation pressure and the kill mud density, since both are computed at the same true vertical depth.", "The influx height and the influx density.", "The initial circulating pressure and the slow circulating rate pressure, which differ only by the shut-in reading."]'::jsonb, 2, 'The density is computed from the height, so an error in the height carries into both.'),
  ('wellcontrol', 'intermediate', 'final', null, 42, 'Reduce this tier to a single claim a colleague could carry away.', '["Hold the bottom hole pressure constant.", "The influx description bridges the shut-in readings and the kick tolerance work of the Expert tier that follows.", "Every deviation from the schedule is either mechanical or it is the well, and the pit volume decides which.", "A kill sheet turns three measurements and a standing part into a schedule somebody can follow."]'::jsonb, 3, 'The others are true and are parts of it. That one is the whole of it.');
